import { filterByQuery } from "@/lib/search";

/**
 * What kind of thing the project *is*, which is what its gutter glyph draws.
 * Kept here as a plain string union so this module stays free of React —
 * `components/project-row.tsx` owns the kind→glyph map.
 */
export type ProjectKind =
  | "cli"
  | "queue"
  | "app"
  | "server"
  | "editor"
  | "canvas"
  | "chat"
  | "vm";

export type Project = {
  name: string;
  description: string;
  url: string;
  /** Live demo or docs, when one exists and is different from `url`. */
  live?: string;
  language: string;
  year: number;
  kind: ProjectKind;
  /** Short third-party signal. Only ever a fact, never a vanity metric. */
  note?: string;
  /**
   * The project's own mark, when it has one, checked into `public/projects`
   * rather than fetched from the project's site — a row must not depend on
   * eight other origins being up, and the Visitor must not be announced to
   * them for looking at this page.
   *
   * `mono` says the file is a silhouette, which is most of them: it is then
   * drawn as a mask in the row's own ink, so a project mark and a kind glyph
   * are the same weight of thing. Marks that carry their own colour (a full
   * composition, not a glyph) drop `mono` and are drawn as an image.
   */
  logo?: { src: string; mono?: boolean };
};

/**
 * Curated, not enumerated. The GitHub account has ~45 repos; eight earn a
 * row here. Order is editorial: the agentic thesis first, then shipped
 * craft. See CONTEXT.md → Project.
 */
const PROJECTS: readonly Project[] = [
  {
    name: "relunar",
    description:
      "CLI-first repro harness for coding agents — deterministic sandboxes, issue reads, and reports.",
    url: "https://github.com/Dhruv2mars/relunar",
    live: "https://relunar.com",
    language: "TypeScript",
    year: 2026,
    kind: "cli",
    note: "published on npm",
    logo: { src: "/projects/relunar.svg", mono: true },
  },
  {
    name: "pi-queue",
    description:
      "FIFO message queue and steering for pi. Queue follow-ups while the agent is still working.",
    url: "https://github.com/Dhruv2mars/pi-queue",
    live: "https://www.npmjs.com/package/@dhruv2mars/pi-queue",
    language: "TypeScript",
    year: 2026,
    kind: "queue",
    note: "published on npm",
  },
  {
    name: "offdex",
    description:
      "Local-first Codex experience across phone, web, and a native bridge.",
    url: "https://github.com/Dhruv2mars/offdex",
    language: "TypeScript",
    year: 2026,
    kind: "app",
    logo: { src: "/projects/offdex.svg", mono: true },
  },
  {
    name: "gunmetal",
    description:
      "Local OpenAI-compatible API routing inference through subscriptions you already pay for.",
    url: "https://github.com/Dhruv2mars/gunmetal",
    live: "https://gunmetalapp.vercel.app",
    language: "Rust",
    year: 2026,
    kind: "server",
    logo: { src: "/projects/gunmetal.svg", mono: true },
  },
  {
    name: "mdv-ts",
    description:
      "Terminal markdown editor and viewer — live editing, formatted preview, OpenTUI rendering.",
    url: "https://github.com/Dhruv2mars/mdv-ts",
    language: "TypeScript",
    year: 2026,
    kind: "editor",
  },
  {
    name: "block",
    description:
      "WebGPU grid explorer for generating and curating logo marks, built on TypeGPU.",
    url: "https://github.com/Dhruv2mars/block",
    live: "https://block-five-zeta.vercel.app",
    language: "TypeScript",
    year: 2026,
    kind: "canvas",
    logo: { src: "/projects/block.svg" },
  },
  {
    name: "codexchat",
    description:
      "Native chat client that runs inference against your existing ChatGPT subscription.",
    url: "https://github.com/Dhruv2mars/codexchat",
    language: "Rust",
    year: 2026,
    kind: "chat",
  },
  {
    name: "openutm-v0",
    description:
      "Cross-platform, open source alternative to UTM for running virtual machines.",
    url: "https://github.com/Dhruv2mars/openutm-v0",
    language: "TypeScript",
    year: 2026,
    kind: "vm",
  },
];

export function getProjects(): readonly Project[] {
  return PROJECTS;
}

export const PROJECT_NAMES = PROJECTS.map((p) => p.name);

/**
 * Everything a row shows, plus the year and the kind, which are things a
 * Visitor looks for by name ("rust", "2026", "cli") even though the kind is
 * only ever drawn as a glyph.
 */
export function searchProjects(
  projects: readonly Project[],
  query: string,
): Project[] {
  return filterByQuery(projects, query, (project) => [
    project.name,
    project.description,
    project.language,
    project.kind,
    project.note,
    project.year,
  ]);
}

/** Host shown on hover, e.g. `relunar.com`. */
export function destinationHost(project: Project): string {
  return new URL(project.live ?? project.url).host.replace(/^www\./, "");
}
import { CopyLink } from "@/components/copy-link";
import { MoreLink } from "@/components/more-link";
import { Panel, PanelHeader, PanelTitle, PanelTitleSup } from "@/components/panel";
import { ProjectRow } from "@/components/project-row";
import { getProjects } from "@/lib/projects";

/** How many rows the home page carries before it defers to `/projects`. */
export const HOME_PROJECT_LIMIT = 5;

/**
 * The sample on the home page: the first few rows and a door to the rest.
 * `/projects` draws its own panel around the whole list — it is a page rather
 * than a section, so it owns its `h1` and its filter, and shares only the row.
 */
export function ProjectsSection({ limit }: { limit?: number }) {
  const projects = getProjects();
  const shown = limit ? projects.slice(0, limit) : projects;
  const hidden = projects.length - shown.length;

  return (
    <Panel id="projects">
      <PanelHeader>
        <PanelTitle>
          Projects
          <PanelTitleSup className="tabular-nums">
            {projects.length}
          </PanelTitleSup>
          <CopyLink id="projects" label="Projects" />
        </PanelTitle>
      </PanelHeader>

      <ul>
        {shown.map((project) => (
          <ProjectRow key={project.name} project={project} />
        ))}
      </ul>

      {hidden > 0 ? <MoreLink href="/projects">All projects</MoreLink> : null}
    </Panel>
  );
}
import type { Metadata } from "next";
import { Panel, PanelHeader, PanelTitle, PanelTitleSup } from "@/components/panel";
import { ProjectSearch } from "@/components/project-search";
import { serializeJsonLd } from "@/lib/json-ld";
import { getProjects } from "@/lib/projects";
import { site } from "@/lib/site";

export const metadata: Metadata = {
  title: "Projects",
  description:
    "Everything I have built and would still defend in a code review.",
  alternates: { canonical: `${site.url}/projects` },
};

/**
 * The projects index, built the way the blog index is: one panel, an `h1` that
 * says the word the nav promised, a count, and a filter over the whole list.
 * The two are the same kind of page — a Visitor who has used one should not
 * have to learn the other.
 */
type ProjectsPageProps = {
  searchParams?: Promise<{ q?: string | string[] }>;
};

export default async function ProjectsPage({ searchParams }: ProjectsPageProps) {
  const projects = [...getProjects()];

  const params = await searchParams;
  const initialQuery = Array.isArray(params?.q)
    ? (params.q[0] ?? "")
    : (params?.q ?? "");

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "CollectionPage",
    "@id": `${site.url}/projects`,
    name: "Projects",
    url: `${site.url}/projects`,
    author: { "@type": "Person", name: site.name, url: site.url },
    hasPart: projects.map((project) => ({
      "@type": "SoftwareSourceCode",
      name: project.name,
      description: project.description,
      codeRepository: project.url,
      programmingLanguage: project.language,
      url: project.live ?? project.url,
    })),
  };

  return (
    <div className="[--separator-height:--spacing(8)]">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
      />

      <Panel id="projects">
        <PanelHeader>
          <PanelTitle as="h1">
            Projects
            <PanelTitleSup className="tabular-nums">
              {projects.length}
            </PanelTitleSup>
          </PanelTitle>
        </PanelHeader>

        <ProjectSearch projects={projects} initialQuery={initialQuery} />
      </Panel>
    </div>
  );
}
import { describe, expect, test } from "bun:test";
import {
  destinationHost,
  getProjects,
  PROJECT_NAMES,
  searchProjects,
} from "@/lib/projects";

describe("Projects are curated, not enumerated", () => {
  test("the list stays small enough to read in one pass", () => {
    expect(getProjects().length).toBeLessThanOrEqual(8);
    expect(new Set(PROJECT_NAMES).size).toBe(PROJECT_NAMES.length);
  });

  test("every Project has a real destination and a description", () => {
    for (const project of getProjects()) {
      expect(() => new URL(project.url)).not.toThrow();
      expect(project.url.startsWith("https://")).toBe(true);
      if (project.live) {
        expect(project.live.startsWith("https://")).toBe(true);
      }
      expect(project.description.length).toBeGreaterThan(20);
      expect(project.language.length).toBeGreaterThan(0);
    }
  });

  test("the hover destination is the host a click actually reaches", () => {
    const [relunar] = getProjects();
    expect(destinationHost(relunar!)).toBe("relunar.com");

    const npm = getProjects().find((p) => p.live?.includes("npmjs.com"));
    expect(npm && destinationHost(npm)).toBe("npmjs.com");
  });

  test("notes are facts, never vanity metrics", () => {
    for (const project of getProjects()) {
      if (!project.note) continue;
      expect(project.note).not.toMatch(/\d/);
    }
  });
});

describe("searchProjects", () => {
  const all = getProjects();

  test("an empty query is not a filter", () => {
    expect(searchProjects(all, "  ")).toHaveLength(all.length);
  });

  test("matches the language, which is what a visitor scans for", () => {
    const rust = searchProjects(all, "rust");
    expect(rust.length).toBeGreaterThan(0);
    expect(rust.every((p) => p.language === "Rust")).toBe(true);
  });

  test("matches the description, not only the name", () => {
    expect(searchProjects(all, "webgpu").map((p) => p.name)).toEqual(["block"]);
  });

  test("a hyphen in the name need not be typed", () => {
    expect(searchProjects(all, "pi queue").map((p) => p.name)).toEqual([
      "pi-queue",
    ]);
  });

  test("matches the year, which is a number on the row", () => {
    expect(searchProjects(all, "2026")).toHaveLength(all.length);
  });

  test("no match is an empty list, never the whole list", () => {
    expect(searchProjects(all, "cobol")).toEqual([]);
  });
});

